152	sealed class JsonlLog
153	{
154	    readonly string _p; readonly string _v; readonly object _g = new();
155	    public JsonlLog(string p, string v) { _p = p; _v = v; }
156	    public void Write(object o)
157	    {
158	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
159	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
160	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
161	    }
162	}
163	
164	// 演練注入 retain_payloads 的落點（v1.2.0 修復後）：客服查詢暫存改為有上限的環狀緩衝——最多 MaxItems 筆、每筆只留前 MaxBodyChars 字與原長度。
165	// v1.1.0 之前是無上限的 List，壓力下把 heap 撐到上限（見 evidence/runs/oom-retained-payloads-*、diagnosis/oom）。
166	static class Retained
167	{
168	    const int MaxItems = 256, MaxBodyChars = 256;
169	    static readonly Queue<(string OrderId, string Head, int Length)> _items = new(); static readonly object _g = new();
170	    public static void Keep(string orderId, string? body)
171	    {
172	        var b = body ?? "";
173	        lock (_g) { _items.Enqueue((orderId, b.Length > MaxBodyChars ? b[..MaxBodyChars] : b, b.Length)); while (_items.Count > MaxItems) _items.Dequeue(); }
174	    }
175	    public static int Count { get { lock (_g) return _items.Count; } }
176	}
177	
178	sealed class Faults
179	{
180	    public int? DropOverQueue; public int DelayMs; public bool RetainPayloads; public bool SyncNotify;
181	    public bool Any => DropOverQueue is not null || DelayMs > 0 || RetainPayloads || SyncNotify;
182	    public static Faults Load(string? path)
183	    {
184	        var f = new Faults();
185	        if (string.IsNullOrEmpty(path) || !File.Exists(path)) return f;
186	        using var doc = JsonDocument.Parse(File.ReadAllText(path)); var r = doc.RootElement;
187	        if (r.TryGetProperty("notify_drop_over_queue", out var q)) f.DropOverQueue = q.GetInt32();
188	        if (r.TryGetProperty("notify_delay_ms", out var d)) f.DelayMs = d.GetInt32();
189	        if (r.TryGetProperty("retain_payloads", out var rp)) f.RetainPayloads = rp.GetBoolean();
190	        if (r.TryGetProperty("sync_notify", out var sn)) f.SyncNotify = sn.GetBoolean();
191	        return f;
192	    }
193	}
194	
195	// 通知 worker：從 channel 取出 → POST sink → 失敗重試 3 次（200／400／800 ms）→ 超過進 dead_letter（NC-05）。
196	// 故障 notify_drop_over_queue（演練用）：佇列深度超過 N 時觸發「壓力延後」路徑。
197	// v1.0.0 的行為是記一行 notify_deferred 後不再重送、sent 計數照加（服務說送了、接收端沒收據）；v1.1.0 改為重排到隊尾、sent 只在 ack 後才加。
198	// 這條故障設計移植自 O 服務 fault-A；是演練用注入，不是自然事故。
199	sealed class NotificationWorker : BackgroundService
200	{
201	    readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly Faults _f; readonly HttpClient _http = new();
202	    readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
203	    static readonly int[] Backoff = { 200, 400, 800 };
204	    const int MaxDeferrals = 5;
205	    public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log, Faults f) { _ch = ch; _m = m; _log = log; _f = f; }
206	    static readonly HttpClient SharedHttp = new();
207	    /// 同步送一次（含重試），供 sync_notify 演練路徑使用；計數規則與 worker 相同。
208	    public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
209	    {
210	        bool sent = false;
211	        for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
212	        {
213	            try
214	            {
215	                var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
216	                var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
217	                sent = resp.IsSuccessStatusCode;
218	            }
219	            catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
220	            if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
221	        }
222	        if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
223	        else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
224	    }
225	    protected override async Task ExecuteAsync(CancellationToken ct)
226	    {
227	        await foreach (var n in _ch.Reader.ReadAllAsync(ct))
228	        {
229	            if (_f.DelayMs > 0) await Task.Delay(_f.DelayMs, ct);
230	            if (_f.DropOverQueue is int q && _ch.Reader.Count > q)
231	            {   // v1.1.0 修復：壓力下不再「假裝送了」。延後＝重排到隊尾（最多 MaxDeferrals 次），sent_total 只在接收端 ack 後才加；延後另計。
232	                if (n.Deferrals < MaxDeferrals)
233	                {
234	                    _m.Inc("notify_deferred_total");
235	                    _log.Write(new { level = "INFO", @event = "notify_deferred", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, queue_depth = _ch.Reader.Count, deferrals = n.Deferrals + 1, requeued = true });
236	                    await _ch.Writer.WriteAsync(n with { Deferrals = n.Deferrals + 1 }, ct);
237	                    continue;
238	                }
239	                _log.Write(new { level = "WARN", @event = "notify_deferral_limit", notification_id = n.NotificationId, deferrals = n.Deferrals, note = "超過延後上限，改走一般送出／重試路徑" });
240	            }
241	            bool sent = false;
242	            for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
243	            {
244	                try
245	                {
246	                    var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
247	                    var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
248	                    sent = resp.IsSuccessStatusCode;
249	                    if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
250	                }
251	                catch (Exception e) when (!ct.IsCancellationRequested)
252	                {
253	                    _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
254	                }
255	                if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
256	            }
257	            if (sent)
258	            {
259	                _m.Inc("notify_sent_total");
260	                _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
261	            }
262	            else
263	            {
264	                _m.Inc("notify_failed_total"); _m.Inc("notify_dead_letter_total");
265	                _log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 });
266	            }
267	        }
268	    }
269	}
